    /**
     * Import and synchronize the user CSV data into Submissions and Divisions table
     */
    public static function importAll(): int
    {
        $csv = self::getCsvData();
        $lines = explode("\n", trim($csv));
        if (empty($lines)) return 0;

        $header = str_getcsv(array_shift($lines));
        $count = 0;

        foreach ($lines as $line) {
            $line = trim($line);
            if (empty($line)) continue;

            $row = str_getcsv($line);
            if (count($row) < 5) continue;

            $timestamp = $row[0] ?? now()->format('Y-m-d H:i:s');
            $nama = trim($row[1] ?? '');
            if (empty($nama) || strtolower($nama) === 'tes') continue;

            $departemen = trim($row[2] ?? 'Umum');
            $jabatan = trim($row[3] ?? '-');
            $computerName = trim($row[4] ?? '');
            $ip = trim($row[5] ?? '-');
            $passwordPc = trim($row[6] ?? '-');
            $os = trim($row[7] ?? '-');
            $manufacturer = trim($row[8] ?? '-');
            $processor = trim($row[9] ?? '-');
            $memory = trim($row[10] ?? '-');
            $displayLink = trim($row[11] ?? '-');
            $soundLink = trim($row[12] ?? '-');
            $inputLink = trim($row[13] ?? '-');

            // Detect if laptop or pc
            $isLaptop = str_contains(strtolower($computerName), 'laptop') || 
                        str_contains(strtolower($os), 'mac') || 
                        str_contains(strtolower($nama), 'laptop');
            $jenisPerangkat = $isLaptop ? 'Laptop' : 'PC Desktop';

            // Ensure division exists
            Division::firstOrCreate(['name' => $departemen]);

            // Unique ID based on employee name and computer name
            $cleanKey = Str::slug($nama . '-' . ($computerName ?: $departemen));
            $id = 'pc_' . $cleanKey;

            $data = [
                'nama' => $nama,
                'departemen' => $departemen,
                'jabatan' => $jabatan,
                'computerName' => $computerName,
                'ip' => $ip,
                'passwordPc' => $passwordPc,
                'os' => $os,
                'manufacturer' => $manufacturer,
                'processor' => $processor,
                'memory' => $memory,
                'displayLink' => $displayLink,
                'soundLink' => $soundLink,
                'inputLink' => $inputLink,
                'jenisPerangkat' => $jenisPerangkat,
            ];

            Submission::updateOrCreate(
                ['id' => $id],
                [
                    'type' => 'pc',
                    'timestamp' => $timestamp,
                    'nama' => $nama,
                    'departemen' => $departemen,
                    'jabatan' => $jabatan,
                    'jenis_perangkat' => $jenisPerangkat,
                    'data' => $data,
                    'synced_to_google' => true,
                ]
            );

            $count++;
        }

        return $count;
    }
